class JSONParseError(Exception):
    pass


def parse_json(text):
    parser = _Parser(text)
    parser.skip_whitespace()
    value = parser.parse_value()
    parser.skip_whitespace()
    if parser.pos != len(text):
        parser.error("Unexpected trailing characters")
    return value


class _Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    # ---------- helpers ----------
    def error(self, msg):
        raise JSONParseError(f"{msg} at position {self.pos}")

    def peek(self):
        return self.text[self.pos] if self.pos < len(self.text) else None

    def advance(self):
        ch = self.peek()
        if ch is None:
            self.error("Unexpected end of input")
        self.pos += 1
        return ch

    def expect(self, ch):
        if self.peek() != ch:
            self.error(f"Expected '{ch}'")
        self.pos += 1

    def skip_whitespace(self):
        while self.peek() in (" ", "\t", "\n", "\r"):
            self.pos += 1

    # ---------- dispatch ----------
    def parse_value(self):
        ch = self.peek()
        if ch == "{":
            return self.parse_object()
        if ch == "[":
            return self.parse_array()
        if ch == '"':
            return self.parse_string()
        if ch == "-" or (ch is not None and ch.isdigit()):
            return self.parse_number()
        if self.text.startswith("true", self.pos):
            self.pos += 4
            return True
        if self.text.startswith("false", self.pos):
            self.pos += 5
            return False
        if self.text.startswith("null", self.pos):
            self.pos += 4
            return None
        self.error("Unexpected character" if ch else "Unexpected end of input")

    # ---------- objects ----------
    def parse_object(self):
        self.expect("{")
        result = {}
        self.skip_whitespace()
        if self.peek() == "}":
            self.pos += 1
            return result
        while True:
            self.skip_whitespace()
            if self.peek() != '"':
                self.error("Expected string key")
            key = self.parse_string()
            self.skip_whitespace()
            self.expect(":")
            self.skip_whitespace()
            result[key] = self.parse_value()
            self.skip_whitespace()
            ch = self.advance()
            if ch == "}":
                return result
            if ch != ",":
                self.error("Expected ',' or '}'")

    # ---------- arrays ----------
    def parse_array(self):
        self.expect("[")
        result = []
        self.skip_whitespace()
        if self.peek() == "]":
            self.pos += 1
            return result
        while True:
            self.skip_whitespace()
            result.append(self.parse_value())
            self.skip_whitespace()
            ch = self.advance()
            if ch == "]":
                return result
            if ch != ",":
                self.error("Expected ',' or ']'")

    # ---------- strings ----------
    ESCAPES = {'"': '"', "\\": "\\", "/": "/", "b": "\b",
               "f": "\f", "n": "\n", "r": "\r", "t": "\t"}

    def parse_string(self):
        self.expect('"')
        out = []
        while True:
            ch = self.advance()
            if ch == '"':
                return "".join(out)
            if ch == "\\":
                esc = self.advance()
                if esc in self.ESCAPES:
                    out.append(self.ESCAPES[esc])
                elif esc == "u":
                    code = self.read_hex4()
                    # Handle UTF-16 surrogate pairs
                    if 0xD800 <= code <= 0xDBFF and self.text.startswith("\\u", self.pos):
                        self.pos += 2
                        low = self.read_hex4()
                        if 0xDC00 <= low <= 0xDFFF:
                            code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
                        else:
                            self.error("Invalid surrogate pair")
                    out.append(chr(code))
                else:
                    self.error(f"Invalid escape '\\{esc}'")
            elif ord(ch) < 0x20:
                self.error("Control character in string")
            else:
                out.append(ch)

    def read_hex4(self):
        hex_str = self.text[self.pos:self.pos + 4]
        if len(hex_str) != 4 or any(c not in "0123456789abcdefABCDEF" for c in hex_str):
            self.error("Invalid \\u escape")
        self.pos += 4
        return int(hex_str, 16)

    # ---------- numbers ----------
    def parse_number(self):
        start = self.pos
        if self.peek() == "-":
            self.pos += 1
        if self.peek() == "0":
            self.pos += 1
        elif self.peek() is not None and self.peek() in "123456789":
            while self.peek() is not None and self.peek().isdigit():
                self.pos += 1
        else:
            self.error("Invalid number")

        is_float = False
        if self.peek() == ".":
            is_float = True
            self.pos += 1
            if not (self.peek() and self.peek().isdigit()):
                self.error("Expected digit after '.'")
            while self.peek() and self.peek().isdigit():
                self.pos += 1
        if self.peek() in ("e", "E"):
            is_float = True
            self.pos += 1
            if self.peek() in ("+", "-"):
                self.pos += 1
            if not (self.peek() and self.peek().isdigit()):
                self.error("Expected digit in exponent")
            while self.peek() and self.peek().isdigit():
                self.pos += 1

        literal = self.text[start:self.pos]
        return float(literal) if is_float else int(literal)
