def parse_json(text):
    i = 0
    n = len(text)

    def error(msg):
        raise ValueError(f"{msg} at position {i}")

    def skip_ws():
        nonlocal i
        while i < n and text[i] in " \t\n\r":
            i += 1

    def parse_value():
        nonlocal i
        skip_ws()
        if i >= n:
            error("Unexpected end of input")
        c = text[i]
        if c == "{": return parse_object()
        if c == "[": return parse_array()
        if c == '"': return parse_string()
        if c == "-" or c.isdigit(): return parse_number()
        if text.startswith("true", i):  i += 4; return True
        if text.startswith("false", i): i += 5; return False
        if text.startswith("null", i):  i += 4; return None
        error(f"Unexpected character {c!r}")

    def parse_object():
        nonlocal i
        i += 1  # skip {
        obj = {}
        skip_ws()
        if i < n and text[i] == "}":
            i += 1
            return obj
        while True:
            skip_ws()
            if i >= n or text[i] != '"':
                error("Expected string key")
            key = parse_string()
            skip_ws()
            if i >= n or text[i] != ":":
                error("Expected ':'")
            i += 1
            obj[key] = parse_value()
            skip_ws()
            if i < n and text[i] == ",":
                i += 1
            elif i < n and text[i] == "}":
                i += 1
                return obj
            else:
                error("Expected ',' or '}'")

    def parse_array():
        nonlocal i
        i += 1  # skip [
        arr = []
        skip_ws()
        if i < n and text[i] == "]":
            i += 1
            return arr
        while True:
            arr.append(parse_value())
            skip_ws()
            if i < n and text[i] == ",":
                i += 1
            elif i < n and text[i] == "]":
                i += 1
                return arr
            else:
                error("Expected ',' or ']'")

    def parse_string():
        nonlocal i
        i += 1  # skip opening quote
        out = []
        escapes = {'"': '"', "\\": "\\", "/": "/", "b": "\b",
                   "f": "\f", "n": "\n", "r": "\r", "t": "\t"}
        while i < n:
            c = text[i]
            if c == '"':
                i += 1
                return "".join(out)
            if c == "\\":
                i += 1
                if i >= n: error("Bad escape")
                e = text[i]
                if e in escapes:
                    out.append(escapes[e]); i += 1
                elif e == "u":
                    hexd = text[i+1:i+5]
                    if len(hexd) != 4: error("Bad unicode escape")
                    out.append(chr(int(hexd, 16)))
                    i += 5
                else:
                    error("Invalid escape")
            else:
                out.append(c); i += 1
        error("Unterminated string")

    def parse_number():
        nonlocal i
        start = i
        if text[i] == "-": i += 1
        while i < n and text[i].isdigit(): i += 1
        is_float = False
        if i < n and text[i] == ".":
            is_float = True
            i += 1
            while i < n and text[i].isdigit(): i += 1
        if i < n and text[i] in "eE":
            is_float = True
            i += 1
            if i < n and text[i] in "+-": i += 1
            while i < n and text[i].isdigit(): i += 1
        s = text[start:i]
        try:
            return float(s) if is_float else int(s)
        except ValueError:
            error("Invalid number")

    result = parse_value()
    skip_ws()
    if i != n:
        error("Trailing data")
    return result
