```ostrel
enum JsonKind {
    Null,
    Bool,
    Number,
    String,
    Array,
    Object,
}

struct Json {
    kind: JsonKind,
    bool_value: bool,
    num_value: float,
    str_value: string,
    arr_value: []Json,
    obj_value: map[string]Json,
}

struct Parser {
    src: string,
    pos: int,
}

fn parse_json(src: string) -> Json {
    let p = Parser {
        src: src,
        pos: 0,
    };

    let value = parse_value(&p);
    skip_ws(&p);

    if p.pos != len(p.src) {
        error("unexpected trailing characters");
    }

    return value;
}

fn parse_value(p: *Parser) -> Json {
    skip_ws(p);

    if eof(p) {
        error("unexpected end of input");
    }

    let c = peek(p);

    if c == 'n' {
        return parse_null(p);
    }

    if c == 't' || c == 'f' {
        return parse_bool(p);
    }

    if c == '"' {
        return Json {
            kind: JsonKind.String,
            str_value: parse_string(p),
        };
    }

    if c == '[' {
        return parse_array(p);
    }

    if c == '{' {
        return parse_object(p);
    }

    if c == '-' || is_digit(c) {
        return Json {
            kind: JsonKind.Number,
            num_value: parse_number(p),
        };
    }

    error("invalid JSON value");
}

fn parse_null(p: *Parser) -> Json {
    expect_text(p, "null");

    return Json {
        kind: JsonKind.Null,
    };
}

fn parse_bool(p: *Parser) -> Json {
    if match_text(p, "true") {
        return Json {
            kind: JsonKind.Bool,
            bool_value: true,
        };
    }

    if match_text(p, "false") {
        return Json {
            kind: JsonKind.Bool,
            bool_value: false,
        };
    }

    error("invalid boolean");
}

fn parse_array(p: *Parser) -> Json {
    expect(p, '[');
    skip_ws(p);

    let items: []Json = [];

    if peek(p) == ']' {
        advance(p);
        return Json {
            kind: JsonKind.Array,
            arr_value: items,
        };
    }

    while true {
        let item = parse_value(p);
        append(&items, item);

        skip_ws(p);

        if peek(p) == ',' {
            advance(p);
            skip_ws(p);
            continue;
        }

        if peek(p) == ']' {
            advance(p);
            break;
        }

        error("expected ',' or ']'");
    }

    return Json {
        kind: JsonKind.Array,
        arr_value: items,
    };
}

fn parse_object(p: *Parser) -> Json {
    expect(p, '{');
    skip_ws(p);

    let obj: map[string]Json = {};

    if peek(p) == '}' {
        advance(p);
        return Json {
            kind: JsonKind.Object,
            obj_value: obj,
        };
    }

    while true {
        skip_ws(p);

        if peek(p) != '"' {
            error("expected object key string");
        }

        let key = parse_string(p);

        skip_ws(p);
        expect(p, ':');

        let value = parse_value(p);
        obj[key] = value;

        skip_ws(p);

        if peek(p) == ',' {
            advance(p);
            skip_ws(p);
            continue;
        }

        if peek(p) == '}' {
            advance(p);
            break;
        }

        error("expected ',' or '}'");
    }

    return Json {
        kind: JsonKind.Object,
        obj_value: obj,
    };
}

fn parse_string(p: *Parser) -> string {
    expect(p, '"');

    let out = "";

    while !eof(p) {
        let c = advance(p);

        if c == '"' {
            return out;
        }

        if c == '\\' {
            if eof(p) {
                error("unterminated escape sequence");
            }

            let esc = advance(p);

            if esc == '"' {
                out += "\"";
            } else if esc == '\\' {
                out += "\\";
            } else if esc == '/' {
                out += "/";
            } else if esc == 'b' {
                out += "\b";
            } else if esc == 'f' {
                out += "\f";
            } else if esc == 'n' {
                out += "\n";
            } else if esc == 'r' {
                out += "\r";
            } else if esc == 't' {
                out += "\t";
            } else if esc == 'u' {
                out += parse_unicode_escape(p);
            } else {
                error("invalid escape sequence");
            }
        } else {
            out += string(c);
        }
    }

    error("unterminated string");
}

fn parse_unicode_escape(p: *Parser) -> string {
    let code = 0;

    for i in 0..4 {
        if eof(p) {
            error("incomplete unicode escape");
        }

        let c = advance(p);
        code = code * 16 + hex_value(c);
    }

    return char_from_codepoint(code);
}

fn parse_number(p: *Parser) -> float {
    let start = p.pos;

    if peek(p) == '-' {
        advance(p);
    }

    if eof(p) {
        error("invalid number");
    }

    if peek(p) == '0' {
        advance(p);
    } else if is_digit_1_9(peek(p)) {
        while !eof(p) && is_digit(peek(p)) {
            advance(p);
        }
    } else {
        error("invalid number");
    }

    if !eof(p) && peek(p) == '.' {
        advance(p);

        if eof(p) || !is_digit(peek(p)) {
            error("invalid fractional number");
        }

        while !eof(p) && is_digit(peek(p)) {
            advance(p);
        }
    }

    if !eof(p) && (peek(p) == 'e' || peek(p) == 'E') {
        advance(p);

        if !eof(p) && (peek(p) == '+' || peek(p) == '-') {
            advance(p);
        }

        if eof(p) || !is_digit(peek(p)) {
            error("invalid exponent");
        }

        while !eof(p) && is_digit(peek(p)) {
            advance(p);
        }
    }

    let text = slice(p.src, start, p.pos);
    return parse_float(text);
}

fn skip_ws(p: *Parser) {
    while !eof(p) {
        let c = peek(p);

        if c == ' ' || c == '\n' || c == '\r' || c == '\t' {
            advance(p);
        } else {
            break;
        }
    }
}

fn expect(p: *Parser, c: char) {
    if eof(p) || peek(p) != c {
        error("unexpected character");
    }

    advance(p);
}

fn expect_text(p: *Parser, text: string) {
    if !match_text(p, text) {
        error("expected " + text);
    }
}

fn match_text(p: *Parser, text: string) -> bool {
    let start = p.pos;

    for i in 0..len(text) {
        if eof(p) || advance(p) != text[i] {
            p.pos = start;
            return false;
        }
    }

    return true;
}

fn peek(p: *Parser) -> char {
    if eof(p) {
        error("unexpected end of input");
    }

    return p.src[p.pos];
}

fn advance(p: *Parser) -> char {
    let c = peek(p);
    p.pos += 1;
    return c;
}

fn eof(p: *Parser) -> bool {
    return p.pos >= len(p.src);
}

fn is_digit(c: char) -> bool {
    return c >= '0' && c <= '9';
}

fn is_digit_1_9(c: char) -> bool {
    return c >= '1' && c <= '9';
}

fn hex_value(c: char) -> int {
    if c >= '0' && c <= '9' {
        return int(c - '0');
    }

    if c >= 'a' && c <= 'f' {
        return int(c - 'a') + 10;
    }

    if c >= 'A' && c <= 'F' {
        return int(c - 'A') + 10;
    }

    error("invalid hex digit");
}
```

