    Bool(bool),
    Number(f64),
    String(string),
    Array(List<JsonValue>),
    Object(Map<string, JsonValue>)
}

struct Parser {
    input: string,
    pos: int
}

impl Parser {
    fn new(input: string) -> Parser {
        return Parser { input: input, pos: 0 };
    }

    fn skip_whitespace(mut self) {
        while self.pos < self.input.length() {
            let ch = self.input.char_at(self.pos);
            if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_value(mut self) -> Result<JsonValue, string> {
        self.skip_whitespace();
        if self.pos >= self.input.length() {
            return Err("Unexpected end of input");
        }

        let ch = self.input.char_at(self.pos);

        match ch {
            '{' => return self.parse_object(),
            '[' => return self.parse_array(),
            '"' => return self.parse_string().map(JsonValue.String),
            't' | 'f' => return self.parse_bool(),
            'n' => return self.parse_null(),
            _ => {
                if ch == '-' || (ch >= '0' && ch <= '9') {
                    return self.parse_number();
                }
                return Err("Unexpected token: " + ch.to_string());
            }
        }
    }

    fn parse_string(mut self) -> Result<string, string> {
        self.pos += 1; // Skip opening quote
        let start = self.pos;

        while self.pos < self.input.length() {
            let ch = self.input.char_at(self.pos);
            if ch == '"' {
                let str_val = self.input.substring(start, self.pos);
                self.pos += 1; // Skip closing quote
                return Ok(str_val);
            }
            self.pos += 1;
        }

        return Err("Unterminated string");
    }

    fn parse_number(mut self) -> Result<JsonValue, string> {
        let start = self.pos;
        while self.pos < self.input.length() {
            let ch = self.input.char_at(self.pos);
            if (ch >= '0' && ch <= '9') || ch == '.' || ch == '-' || ch == '+' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let num_str = self.input.substring(start, self.pos);
        return Ok(JsonValue.Number(num_str.to_float()));
    }

    fn parse_array(mut self) -> Result<JsonValue, string> {
        self.pos += 1; // Skip '['
        let mut elements = List.new();

        self.skip_whitespace();
        if self.input.char_at(self.pos) == ']' {
            self.pos += 1;
            return Ok(JsonValue.Array(elements));
        }

        loop {
            let val = self.parse_value()?;
            elements.push(val);

            self.skip_whitespace();
            let ch = self.input.char_at(self.pos);
            if ch == ']' {
                self.pos += 1;
